import java.util.List;

record Order(long id, String status, double amount, boolean isPaid) {}

class OrderValidator {
    boolean hasAnyUnpaidOrders(List<Order> orders) {
        return orders.stream().anyMatch(order -> !order.isPaid());
    }

    boolean areAllOrdersCompleted(List<Order> orders) {
        return orders.stream()
            .allMatch(order -> "COMPLETED".equals(order.status()));
    }

    boolean hasNoNegativeAmounts(List<Order> orders) {
        return orders.stream().noneMatch(order -> order.amount() < 0);
    }

    boolean canProcessBatch(List<Order> orders) {
        return !orders.isEmpty()
            && orders.stream().allMatch(Order::isPaid)
            && orders.stream().noneMatch(order -> order.amount() < 0);
    }
}
