import java.util.List;
import java.util.Optional;

record Order(long id, long amountCents, int itemCount) {}

class OrderAnalytics {
    long totalRevenueCents(List<Order> orders) {
        return orders.stream()
            .map(Order::amountCents)
            .reduce(0L, Long::sum);
    }

    Optional<Order> largestOrder(List<Order> orders) {
        return orders.stream().reduce((left, right) ->
            left.amountCents() >= right.amountCents() ? left : right);
    }

    int totalItemCount(List<Order> orders) {
        return orders.stream().map(Order::itemCount).reduce(0, Integer::sum);
    }

    String summary(List<Order> orders) {
        return orders.stream()
            .map(order -> String.format("#%d: %d cents",
                order.id(), order.amountCents()))
            .reduce((left, right) -> left + ", " + right)
            .orElse("");
    }
}
